import{z as s,x as o,o as t,c as p,q as r,j as l,D as B,d as e,s as A,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"OIS 与多曲线","description":"","frontmatter":{"title":"OIS 与多曲线","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/multi-curve-ois.md","filePath":"quant/multi-curve-ois.md","lastUpdated":1791063341000}'),I={name:"quant/multi-curve-ois.md"};function O(d,a,S,D,u,h){const i=o("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="ois-与多曲线" tabindex="-1">OIS 与多曲线 <a class="header-anchor" href="#ois-与多曲线" aria-label="Permalink to &quot;OIS 与多曲线&quot;">​</a></h1><div class="epigraph"><p>抵押衍生品的折现应跟随隔夜指数互换曲线；LIBOR 合同的浮动端仍按 LIBOR 远期投影——一条曲线不能再同时做两件事。</p><footer>—— 危机后市场惯例；Bianchetti, Two Curves, One Price, Risk, 2010；Hull and White, LIBOR vs. OIS: The Derivatives Discounting Dilemma</footer></div><p><a href="/quant/curve-bootstrap">上一课</a>按到期逐个解折现或远期节点，使构建集在给定插值下精确重定价，并点名多曲线下同一算法分别服务折现曲线与投影曲线。缺口正是「分别」：2008 年以前许多台子用同一条 LIBOR 互换曲线既折现又预测浮动现金流；危机中 LIBOR–OIS 基差撑开，再也不能当微小摩擦。有抵押衍生品的折现更靠近 OIS；浮动端仍挂钩 3M LIBOR 的合同，投影必须用 3M 曲线。本课写折现曲线与投影曲线成对出现。不重推自助法的一维求解。后课久期默认已经知道 Delta 是「曲线 × 期限」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单曲线下，标准浮动端在重置与支付匹配时，现值可收成面额减终折现，互换利率是折现加权远期平均，远期由同一 \\(P\\) 的比得到。基差一宽，3M LIBOR 远期不再等于 OIS 隐含的三个月复利，用 OIS 折现却用 LIBOR 自助的远期，价格会变；用 LIBOR 折现抵押组合，又与 CSA 的隔夜利息不一致，出现虚假 P&amp;L。问题是明确三件事：折现用哪条曲线、每个浮动指标用哪条投影曲线、不同期限 LIBOR（1M/3M/6M）之间的基差如何用额外曲线或基差互换吸收。</p><p><span class="marginnote">「OIS」（隔夜指数互换）翻译成大白话：双方交换「一段时间里每天隔夜利率滚动复利」与一个固定利率。因为抵押金按隔夜利息计息、期限极短，它几乎不含银行违约风险，成了市场公认的「无风险折现基准」。LIBOR 则是「银行之间借三个月钱」的利率，含信用与流动性溢价——2008 年两者差过一百多个基点，旧的单一曲线模型从此失灵。</span></p><p>外汇与跨货币 CSA 还引入美元以外的抵押与交叉货币基差，使折现变成「本币 OIS 调整后的曲线」。那是多曲线的下一层；本篇先把单币种、抵押利率衍生品的双曲线结构说清。</p><h3 id="抵押、无抵押与折现" tabindex="-1">抵押、无抵押与折现 <a class="header-anchor" href="#抵押、无抵押与折现" aria-label="Permalink to &quot;抵押、无抵押与折现&quot;">​</a></h3><p>理想 CSA：每日足额现金抵押，报酬指数为隔夜有效利率，则增量现金流的折现接近 OIS（或该指数的互换曲线）。无抵押组合的折现应反映对手方信用与自身融资，那是 CVA/FVA 的领域，不应假装仍是 LIBOR 曲线就完事，也不应无条件改用 OIS。Hull–White 的「两难」正在于：同一法律主体的不同交易可能分属不同 CSA，折现不能全球唯一。多曲线首先是估值约定，然后才是曲线构建技术。</p><p><span class="marginnote">OIS 曲线由隔夜指数互换自助，不是「把 LIBOR 曲线减一个常数」。形状可以不同，尤其在短端政策利率路径与长端供需上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先自助 OIS：输入是隔夜存款、短端 OIS、长端 OIS 互换，得到折现 \\(P^D(0,T)\\)。再自助投影：对 3M LIBOR 互换，固定端用 \\(P^D\\) 折现，浮动端是 \\(\\sum P^D(0,T_i)\\delta_i F^{3M}(0;T_{i-1},T_i)\\)，其中 \\(F^{3M}\\) 来自投影折现 \\(P^{3M}\\) 或其等价远期曲线。已知 \\(P^D\\) 时，每个新互换到期解投影曲线的一个新节点。1M、6M 用基差互换或对应期限的互换再解 \\(P^{1M},P^{6M}\\)。FRA 直接报投影远期，仍要用 \\(P^D\\) 折现其结算。</p><p>欧式期权与上限的标的是投影远期，微笑可以仍用 <a href="/quant/sabr">SABR</a> 标记；估值时贴现用 \\(P^D\\)。旧单曲线公式里「互换 Delta」混着折现风险与远期风险；多曲线必须拆成 OIS Delta 与 LIBOR 基差 Delta，否则对冲会用错工具。</p><h3 id="公式层的最小改动" tabindex="-1">公式层的最小改动 <a class="header-anchor" href="#公式层的最小改动" aria-label="Permalink to &quot;公式层的最小改动&quot;">​</a></h3><p>确定现金流（固定端、已确定的浮动支付）只碰 \\(P^D\\)。尚未确定的浮动，用对应指标的远期乘以年分数，再乘 \\(P^D\\)。不要用 \\(P^{3M}\\) 去折现 3M 现金流——\\(P^{3M}\\) 在构造上往往只是为了生成 \\(F^{3M}\\) 的辅助对象，未必是可交易的零息债券价格。Bianchetti 强调价格只有一个：所有现金流最终都用折现曲线送到今天，投影曲线只负责期望浮动。</p><p><span class="marginnote">常见误区：初学者容易以为多曲线就是「每条曲线各自为政」。实际上价格只有一个：投影曲线只负责「估计浮动利率的期望」，最后一分钱都要用折现曲线 \\(P^D\\) 送回今天。拿 \\(P^{3M}\\) 去折 3M 现金流是典型错误——它构造上只是生成远期的辅助对象，不对应可交易的债券价格。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LIBOR 含银行信用与流动性，OIS 更接近有抵押的隔夜。二者之差是基差，本身可交易（LIBOR–OIS 基差互换）。危机后基差的水平与波动都大到必须当独立风险因子。单曲线等于假设基差恒为零；多曲线把基差的期限结构显式化。IBOR 改革用 SOFR、€STR 等几乎无信用的隔夜替代 LIBOR 之后，折现与投影在隔夜复利互换上可以重新靠近，但期限 SOFR、跨期限基差、历史 LIBOR 残余合同仍然强制多曲线或至少多指数。</p><p><span class="marginnote">数字实例：3M LIBOR \\(=4.30\\%\\)、OIS \\(=4.00\\%\\)，基差 \\(30\\) 个基点。一笔名义 \\(1\\) 亿、剩余期限约 \\(5\\) 年的互换，仅把折现从 LIBOR 曲线换到 OIS 曲线，现值就能动百万美元量级——单曲线时代这被当作噪声，危机中它大到能把整本账打乱，这就是基差必须当独立风险因子的算术理由。</span></p><p>对冲上，抵押互换的折现风险用 OIS 对冲，浮动指标风险用对应互换或期货对冲。用旧的「单一互换曲线 01」会在基差变动时出现无法解释的 P&amp;L。这与 <a href="/quant/key-rate-duration">关键利率久期</a> 的分桶思想一致，只是桶的维度从「期限」增加了「哪一条曲线」。</p>',20)),(t(),l(n,null,{default:B(()=>[A(i,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%223M%20LIBOR%20%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20FIX%5B%22%E5%9B%BA%E5%AE%9A%E8%85%BF%EF%BC%9A%E5%B7%B2%E7%9F%A5%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%0A%20%20S%20--%3E%20FLT%5B%22%E6%B5%AE%E5%8A%A8%E8%85%BF%EF%BC%9A%E6%9C%AA%E7%A1%AE%E5%AE%9A%E5%88%A9%E6%81%AF%22%5D%0A%20%20FIX%20--%3E%20D%5B%22%E7%94%A8%E6%8A%98%E7%8E%B0%E6%9B%B2%E7%BA%BF%20P%5ED%20%E6%8A%98%E7%8E%B0%22%5D%0A%20%20FLT%20--%3E%20PR%5B%22%E7%94%A8%E6%8A%95%E5%BD%B1%E6%9B%B2%E7%BA%BF%E7%AE%97%E8%BF%9C%E6%9C%9F%20F%5E%7B3M%7D%22%5D%0A%20%20PR%20--%3E%20D2%5B%22%E8%BF%9C%E6%9C%9F%E4%B9%98%E5%B9%B4%E5%88%86%E6%95%B0%EF%BC%8C%E5%86%8D%E4%B9%98%20P%5ED%20%E6%8A%98%E7%8E%B0%22%5D%0A%20%20D%20--%3E%20PV%5B%22%E4%BA%92%E6%8D%A2%E7%8E%B0%E5%80%BC%EF%BC%9A%E4%BB%B7%E6%A0%BC%E5%8F%AA%E6%9C%89%E4%B8%80%E4%B8%AA%22%5D%0A%20%20D2%20--%3E%20PV%0A%20%20X%5B%22%E9%94%99%E8%AF%AF%EF%BC%9A%E7%9B%B4%E6%8E%A5%E7%94%A8%20P%5E%7B3M%7D%20%E6%8A%98%E7%8E%B0%22%5D%20--%3E%20BAD%5B%22%E6%8A%98%E7%8E%B0%E4%B8%8E%E6%8A%95%E5%BD%B1%E6%B7%B7%E7%94%A8%20%E2%86%92%20%E8%99%9A%E5%81%87%20P%26L%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h3",{id:"与自助法、远期定义的衔接",tabindex:"-1"},[e("与自助法、远期定义的衔接 "),E("a",{class:"header-anchor",href:"#与自助法、远期定义的衔接","aria-label":'Permalink to "与自助法、远期定义的衔接"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("远期定义仍是「适当曲线上两个零息之比」，但必须声明是哪条曲线。OIS 远期描述隔夜复利的未来路径；3M LIBOR 远期描述 3M 定盘。无套利不再要求二者相等，只要求各自与可交易互换、基差互换一致。这是对 "),E("a",{href:"/quant/spot-forward-df"},"即期、远期与折现"),e(" 单曲线恒等式的限制性说明：恒等式在单条曲线内成立，跨曲线相等不是恒等式。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"把多曲线理解成「多做几次 Bootstrap」是对的；理解成「利率有了两个真值」是错的。真值是合同现金流加 CSA；曲线是用来表示这些现金流的坐标。")],-1)),(t(),l(n,null,{default:B(()=>[A(i,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20CSA%5B%22CSA%20%2F%20%E6%8A%B5%E6%8A%BC%E6%8C%87%E6%95%B0%22%5D%20--%3E%20OIS%5B%22OIS%20%E6%8A%98%E7%8E%B0%E6%9B%B2%E7%BA%BF%20P%5ED%22%5D%0A%20%20IBOR%5B%22LIBOR%20%E6%88%96%E6%9C%9F%E9%99%90%E5%88%A9%E7%8E%87%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20Proj%5B%22%E6%8A%95%E5%BD%B1%E6%9B%B2%E7%BA%BF%20F%5E%7B3M%7D%20%E7%AD%89%22%5D%0A%20%20OIS%20--%3E%20Price%5B%22%E6%89%80%E6%9C%89%E7%8E%B0%E9%87%91%E6%B5%81%E7%94%A8%20P%5ED%20%E6%8A%98%E7%8E%B0%22%5D%0A%20%20Proj%20--%3E%20Float%5B%22%E6%B5%AE%E5%8A%A8%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20Float%20--%3E%20Price%0A%20%20Basis%5B%221M%2F3M%2F6M%20%E5%9F%BA%E5%B7%AE%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20Proj%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多曲线定价仍常假设确定性基差或确定性曲线，把波动只放在投影远期的微笑上。基差本身随机时，抵押凸性、交叉货币与 Quanto 需要更重的模型，不应把 2010 年的双曲线确定性框架写成已经包含全部凸性。无 CSA 或弱 CSA 不能无条件 OIS 折现。清算中心与双边 CSA 的报酬指数若不同，折现曲线应按净额集分割。</p><p>Bianchetti（2010）与 Hull–White 的 OIS/LIBOR 讨论是危机后惯例的枢纽文献；它们不规定 SOFR 过渡后的每一张合同。构建细节仍依赖 Hagan–West 插值与日历。读旧论文里的单曲线数值例，不能直接当今日抵押组合的估值。</p><p><span class="marginnote">LIBOR 停用后，「多曲线」没有过时：变成 OIS 折现加期限利率、RFR 复利、跨币种基差。名字还在，指标换了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>危机后抵押衍生品用 OIS 折现，IBOR 浮动端用自身投影曲线；单曲线假设基差为零，已与市场矛盾。</li><li>价格仍只有一个：投影给出浮动期望，折现把所有现金流送到今天。</li><li>不同期限 IBOR 需要各自曲线或基差互换；对冲要拆 OIS 01 与基差 01。</li><li>\\(P^{3M}\\) 常是生成远期的辅助，不应用它折现。</li><li>CSA 细节决定能否 OIS 折现；无抵押是另一套信用与融资调整。</li><li>出处：Bianchetti, <em>Risk</em>, 2010；Hull and White, LIBOR vs. OIS；构建技术见 Hagan and West, 2006；入门恒等式见 Hull 教科书。</li></ul>',6))])}const R=s(I,[["render",O]]);export{m as __pageData,R as default};
